import { NextResponse } from 'next/server';

interface PostRecord {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
}

interface UpdatePostBody {
  title?: string;
  content?: string;
}

interface MessageResponse {
  message: string;
}

interface ErrorResponse {
  error: string;
}

interface PostRouteContext {
  params: Promise<{
    id: string;
  }>;
}

function parsePostId(rawId: string): number | null {
  const parsedId = Number.parseInt(rawId, 10);
  return Number.isNaN(parsedId) ? null : parsedId;
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext,
): Promise<NextResponse<PostRecord | ErrorResponse>> {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post: PostRecord = {
    id: parsedId,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext,
): Promise<NextResponse<PostRecord | ErrorResponse>> {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody = {};

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const updatedPost: PostRecord = {
    id: parsedId,
    title: body.title ?? "'`Post ${id}`,
    content: body.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext,
): Promise<NextResponse<MessageResponse | ErrorResponse>> {
  const { id } = await params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: '"'Invalid post id' }, { status: 400 });
  }

  return NextResponse.json({ message: "'`Post ${id} deleted successfully` });
}
